  /**
   * @method
   * @name zebpay#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/public-endpoints.md#get-klinescandlesticks
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/public-endpoints/market.md#-get-k-lines-ohlcv-data
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.endtime] the latest time in ms to fetch orders for
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(isEqual(limit, std::any{}))) {
                   limit = 100; // default is 200
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ::setValue(request, std::string("interval"),
                              this->safeString(this->timeframes, timeframe,
                                               timeframe));
                 } else {
                   ::setValue(request, std::string("interval"), timeframe);
                 }
                 if (isTrue(isTrue((isEqual(
                                ::getValue(market, std::string("contract")),
                                true))) &&
                            isTrue((!isEqual(limit, std::any{}))))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                      true))) {
                     ::setValue(request, std::string("startTime"), since);
                   } else {
                     ::setValue(request, std::string("since"), since);
                   }
                 }
                 std::any until = this->safeInteger2(
                     params, std::string("until"), std::string("endtime"));
                 if (isTrue(!isEqual(until, std::any{}))) {
                   ::setValue(request, std::string("endTime"), until);
                   params =
                       this->omit(params, ccxt::list{std::string("endtime"),
                                                     std::string("until")});
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   if (isTrue(isTrue(isEqual(until, std::any{})) ||
                              isTrue(isEqual(since, std::any{})))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(
                                 " fetchOHLCV() requires a both a since and "
                                 "until/endtime parameter for spot markets"))));
                   }
                   response = awaitValue(this->publicSpotGetV2MarketKlines(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->publicSwapPostV1MarketKlines(
                       this->extend(request, params)));
                 }
                 //
                 //             [
                 //                 [
                 //                     "1670608800000",
                 //                     "17071",
                 //                     "17073",
                 //                     "17027",
                 //                     "17055.5",
                 //                     "268611",
                 //                     "15.74462667"
                 //                 ],
                 //                 [
                 //                     "1670605200000",
                 //                     "17071.5",
                 //                     "17071.5",
                 //                     "17061",
                 //                     "17071",
                 //                     "4177",
                 //                     "0.24469757"
                 //                 ],
                 //                 [
                 //                     "1670601600000",
                 //                     "17086.5",
                 //                     "17088",
                 //                     "16978",
                 //                     "17071.5",
                 //                     "6356",
                 //                     "0.37288112"
                 //                 ]
                 //             ]
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

