  /**
   * @method
   * @name zebpay#createOrder
   * @description Create an order on the exchange
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/private-endpoints.md#place-new-order
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/private-endpoints/trade.md#--create-order
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} type 'limit' or 'market'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount the amount of currency to trade
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.formType] The price at which a trigger order is
   * triggered at
   * @param {string} [params.marginAsset] The asset the order creates, default
   * is INR.
   * @param {boolean} [params.takeProfit] Takeprofit flag for the order.
   * @param {boolean} [params.stopLoss] Stop loss flag for the order.
   * @param {string} [params.positionId] PositionId of the order.
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any upperCaseType = toUpperCase(type);
                 std::any takeProfitPrice =
                     this->safeString(params, std::string("takeProfitPrice"));
                 std::any stopLossPrice =
                     this->safeString(params, std::string("stopLossPrice"));
                 params = this->omit(
                     params, ccxt::list{std::string("marginAsset"),
                                        std::string("takeProfitPrice"),
                                        std::string("takeProfitPrice")});
                 if (isTrue(isEqual(side, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a side argument"))));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), toUpperCase(side)},
                 };
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   std::any requestparamsVariable = this->orderRequest(
                       symbol, type, amount, request, price, params);
                   request = ::getValue(requestparamsVariable, 0);
                   params = ::getValue(requestparamsVariable, 1);
                   response = awaitValue(this->privateSpotPostV2ExOrders(
                       this->extend(request, params)));
                 } else {
                   std::any marginAsset = this->safeString(
                       params, std::string("marginAsset"), std::string("INR"));
                   std::any formType =
                       this->safeStringUpper(params, std::string("formType"),
                                             std::string("ORDER_FORM"));
                   ::setValue(request, std::string("formType"), formType);
                   ::setValue(
                       request, std::string("amount"),
                       this->parseToNumeric(this->amountToPrecision(
                           ::getValue(market, std::string("id")), amount)));
                   ::setValue(request, std::string("marginAsset"), marginAsset);
                   std::any hasTP = !isEqual(takeProfitPrice, std::any{});
                   std::any hasSL = !isEqual(stopLossPrice, std::any{});
                   if (isTrue(isTrue(hasTP) || isTrue(hasSL))) {
                     if (isTrue(hasTP)) {
                       ::setValue(request, std::string("takeProfitPrice"),
                                  this->parseToNumeric(this->priceToPrecision(
                                      symbol, takeProfitPrice)));
                     }
                     if (isTrue(hasSL)) {
                       ::setValue(request, std::string("stopLossPrice"),
                                  this->parseToNumeric(this->priceToPrecision(
                                      symbol, stopLossPrice)));
                     }
                     response =
                         awaitValue(this->privateSwapPostV1TradeOrderAddTPSL(
                             this->extend(request, params)));
                   } else {
                     ::setValue(request, std::string("type"), upperCaseType);
                     if (isTrue(isEqual(type, std::string("limit")))) {
                       if (isTrue(isEqual(price, std::any{}))) {
                         throw ArgumentsRequired(toString(
                             add(this->id,
                                 std::string(" createOrder() requires a price "
                                             "argument for limit orders"))));
                       }
                       ::setValue(request, std::string("price"),
                                  this->parseToNumeric(
                                      this->priceToPrecision(symbol, price)));
                     }
                     response = awaitValue(this->privateSwapPostV1TradeOrder(
                         this->extend(request, params)));
                   }
                 }
                 //
                 //    {
                 //        "data": {
                 //            "clientOrderId": "619717484f1d010001510cde",
                 //        },
                 //    }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOrder(data, market);
               })
        .share();
  }

  virtual std::any orderRequest(std::any symbol, std::any type, std::any amount,
                                std::any request, std::any price = std::any{},
                                std::any params = ccxt::dict{}) {
    std::any upperCaseType = toUpperCase(type);
    std::any triggerPrice =
        this->safeString(params, std::string("stopLossPrice"));
    std::any quoteOrderQty = this->safeString2(
        params, std::string("quoteOrderQty"), std::string("cost"), std::any{});
    std::any timeInForce = this->safeString(params, std::string("timeInForce"),
                                            std::string("GTC"));
    std::any clientOrderId =
        this->safeString(params, std::string("clientOrderId"), this->uuid());
    params = this->omit(params, ccxt::list{std::string("stopLossPrice"),
                                           std::string("cost"),
                                           std::string("timeInForce"),
                                           std::string("clientOrderId")});
    ::setValue(request, std::string("type"), upperCaseType);
    ::setValue(request, std::string("clientOrderId"), clientOrderId);
    ::setValue(request, std::string("timeInForce"), timeInForce);
    if (isTrue(isEqual(upperCaseType, std::string("MARKET")))) {
      if (isTrue(isEqual(quoteOrderQty, std::any{}))) {
        throw ExchangeError(toString(
            add(this->id,
                std::string(" spot market orders require cost in params"))));
      }
      ::setValue(request, std::string("quoteOrderAmount"),
                 this->costToPrecision(symbol, quoteOrderQty));
    } else {
      if (isTrue(!isEqual(triggerPrice, std::any{}))) {
        ::setValue(request, std::string("stopLossPrice"),
                   this->priceToPrecision(symbol, triggerPrice));
      }
      ::setValue(request, std::string("amount"),
                 this->amountToPrecision(symbol, amount));
      ::setValue(request, std::string("price"),
                 this->priceToPrecision(symbol, price));
    }
    return ccxt::list{request, params};
  }

  /**
   * @method
   * @name zebpay#cancelOrder
   * @description cancels an open order
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/private-endpoints.md#cancel-order
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/private-endpoints/trade.md#-cancel-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.timestamp] extra parameters specific to the
   * exchange API endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any response = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ::setValue(request, std::string("orderId"), id);
                   response = awaitValue(this->privateSpotDeleteV2ExOrder(
                       this->extend(request, params)));
                 } else {
                   std::any clientOrderId =
                       this->safeString(params, std::string("clientOrderId"));
                   if (isTrue(isEqual(clientOrderId, std::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" cancelOrder() requires a clientOrderId "
                                     "parameter for swap orders"))));
                   }
                   ::setValue(request, std::string("clientOrderId"),
                              clientOrderId);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   response = awaitValue(this->privateSwapDeleteV1TradeOrder(
                       this->extend(request, params)));
                 }
                 //
                 //    {
                 //        "data": {
                 //            "clientOrderId": "619714b8b6353000014c505a",
                 //            "status": "canceled"
                 //        },
                 //    }
                 //
                 return this->parseOrder(this->safeDict(
                     response, std::string("data"), ccxt::dict{}));
               })
        .share();
  }

  /**
   * @method
   * @name zebpay#cancelAllOrders
   * @description cancels all open orders
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/private-endpoints.md#cancel-all-orders
   * @param {string} [symbol] unified symbol of the market the orders were made
   * in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.timestamp] the timestamp of the request in ms
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("cancelAllOrders"), std::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 if (isTrue(!isEqual(type, std::string("spot")))) {
                   throw NotSupported(toString(
                       add(add(add(this->id,
                                   std::string(
                                       " cancelAllOrders() does not support ")),
                               type),
                           std::string(" markets"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any response = awaitValue(
                     this->privateSpotDeleteV2ExOrdersCancelAll(params));
                 //
                 //    {
                 //        "data": {
                 //            "orderId": "12345",
                 //            "symbol": 'BTC-INR
                 //        },
                 //    }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any parsedOrder = this->parseOrder(data);
                 return ccxt::list{parsedOrder};
               })
        .share();
  }

  /**
   * @method
   * @name zebpay#fetchOpenOrders
   * @description fetches information on multiple open orders made by the user
   * @see [Spot]
   * https://github.com/zebpay/zebpay-api-references/blob/main/spot/api-reference/private-endpoints.md#get-orders
   * @see [Swap]
   * https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/private-endpoints/trade.md#-get-open-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = std::any{};
                 std::any orders = ccxt::list{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ::setValue(request, std::string("currentPage"), 1);
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("pageSize"), limit);
                   }
                   response = awaitValue(this->privateSpotGetV2ExOrders(
                       this->extend(request, params)));
                   std::any responseData = this->safeDict(
                       response, std::string("data"), ccxt::dict{});
                   orders = this->safeList(responseData, std::string("items"),
                                           ccxt::list{});
                 } else {
                   if (isTrue(!isEqual(since, std::any{}))) {
                     ::setValue(request, std::string("since"), since);
                   }
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("limit"), limit);
                   }
                   response =
                       awaitValue(this->privateSwapGetV1TradeOrderOpenOrders(
                           this->extend(request, params)));
                   std::any responseData = this->safeDict(
                       response, std::string("data"), ccxt::dict{});
                   orders = this->safeList(responseData, std::string("data"),
                                           ccxt::list{});
                 }
                 //
                 //     {
                 //         "data": {
                 //             "nextTimeStamp": null,
                 //             "totalCount": 100,
                 //             "data": [
                 //                 {
                 //                     "clientOrderId":
                 //                     "64507d02921f1c0001ff6892-123-zeb",
                 //                     "datetime": "2025-03-14T14:34:34.4567",
                 //                     "timestamp": 1741962557553,
                 //                     "status": "open",
                 //                     "symbol": "BTCINR",
                 //                     "type": "market",
                 //                     "timeInForce": "GTC",
                 //                     "side": "buy",
                 //                     "price": 700000,
                 //                     "amount": 0.002,
                 //                     "filled": null,
                 //                     "remaining": 0.002,
                 //                     "trades": []
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 return this->parseOrders(orders, market, std::any{}, limit);
               })
        .share();
  }

